const size_t EMBEDDED_ICONS_COUNT =
    sizeof(EMBEDDED_ICONS) / sizeof(EMBEDDED_ICONS[0]);

const EmbeddedIcon* findEmbeddedIcon(const char* name) {
  for (size_t i = 0; i < EMBEDDED_ICONS_COUNT; i++) {
    char iconName[32];
    strcpy_P(iconName, (PGM_P)pgm_read_ptr(&EMBEDDED_ICONS[i].name));
    if (strcmp(iconName, name) == 0) {
      return &EMBEDDED_ICONS[i];
    }
  }
  return nullptr;
}

#else  // !(ENABLE_HTTP_SERVER || ENABLE_OLED_DISPLAY)

// Keep unconditional callers linkable in headless builds.
extern const EmbeddedIcon EMBEDDED_ICONS[] = {};
extern const size_t EMBEDDED_ICONS_COUNT = 0;

const EmbeddedIcon* findEmbeddedIcon(const char* /*name*/) {
  return nullptr;
}

#endif  // ENABLE_HTTP_SERVER || ENABLE_OLED_DISPLAY
